  setView(`<section class="page-wrap">${heading('MADE TO BE SHARED',anonymous?'把你的日主，分享给想认识的人。':'一张卡片，打开新的相遇。','只展示你确认公开的信息。选择建议版式后，下载 PNG 图片。')}<div class="poster-layout"><div class="poster-stage"><canvas id="poster-canvas" width="${format.width}" height="${format.height}" aria-label="分享海报预览"></canvas><div id="carousel-nav" class="carousel-nav" hidden><button type="button" class="secondary" id="carousel-prev">上一页</button><span id="carousel-counter">1 / 5</span><button type="button" class="secondary" id="carousel-next">下一页</button></div></div><div class="poster-settings surface"><div class="eyebrow">MAKE IT YOURS</div><h2>你的三张分享图片。</h2><div class="poster-output-options"><label>发布到<select id="poster-platform">${[['wechat','朋友圈 · 3:4'],['xiaohongshu','小红书 · 3:4'],['douyin','抖音 · 9:16'],['channels','视频号 · 9:16']].map(([value,label])=>`<option value="${value}" ${state.platform===value?'selected':''}>${label}</option>`).join('')}</select></label></div><p id="poster-format-note" class="fine-print"></p><details id="poster-adjustments" class="poster-adjustments"><summary>调整内容</summary><label id="carousel-qr-option" class="check-line" hidden><input id="carousel-tail-qr" type="checkbox" ${tailQrEnabled()?'checked':''}>尾页附二维码</label><p id="carousel-policy-note" class="fine-print" hidden>小红书默认无二维码尾页。带码素材用于朋友圈或评审；站外码准入未核实，不保证可发布。</p><div class="style-options">${[['五行交友','#e7eddf','我是谁 · 想认识谁'],['个人亮点','#2d433b','三个亮点 · 真实的我'],['兴趣搭子','#e8d59f','喜欢什么 · 一起做'],['邀请测试','#dce4c9','没有档案也能邀请']].map(([name,color,sub],i)=>`<button class="style-choice ${state.theme===i?'active':''}" data-theme="${i}" ${!hasSubject&&i!==3?'disabled':''}><span class="swatch" style="background:${color}"></span><span>${name}<small>${sub}</small></span></button>`).join('')}</div><div id="poster-person-settings" ${state.theme===3?'hidden':''}>${anonymous?`<div class="poster-light-fields"><label>昵称（选填）<input id="poster-nickname" maxlength="20" value="${esc(state.anonymousNickname||'')}" placeholder="不填也可以生成"></label><label>想一起做什么（选填）<input id="poster-hobbies" maxlength="80" value="${esc(state.anonymousHobbies||'')}" placeholder="如 羽毛球、看展"></label><label class="check-line"><input type="checkbox" id="poster-public-stem" ${state.anonymousStem!==false?'checked':''}>展示我的日主</label><label class="check-line"><input type="checkbox" id="poster-public-zodiac" ${state.anonymousZodiac!==false?'checked':''}>展示我的生肖</label><label class="check-line"><input type="checkbox" id="poster-public-targets" ${state.anonymousTargets!==false?'checked':''}>展示文化参考方向</label><p class="fine-print">不保存成个人档案，也不会加入人库。生日、出生城市和时间均不进入海报。</p></div>`:''}${p&&Object.keys(p.fields).length?`<label class="field-label">优先突出哪些亮点（最多三项）</label><div class="poster-highlight-options">${Object.keys(p.fields).map(key=>`<label class="chip-option"><input type="checkbox" data-highlight="${key}" ${state.highlightKeys?.includes(key)?'checked':''}><span>${esc(fields[key].split(' / ')[0])}</span></label>`).join('')}</div>`:''}<label for="poster-caption" class="field-label">分享时，想说的一句话</label><textarea id="poster-caption" maxlength="60" rows="3">${esc(state.caption??defaultPosterCaption(p))}</textarea><div class="caption-presets"><button type="button" class="text-button" data-caption="elements">从五行聊起</button><button type="button" class="text-button" data-caption="hobbies">约共同爱好</button></div><p class="fine-print">请使用本人的真实信息，不会替你编造经历或条件。</p></div><div id="poster-link-content"></div></details><label class="check-line"><input type="checkbox" id="poster-confirm">我已检查三页公开内容，同意生成分享图片。</label><button id="generate-gallery" class="primary">生成3张图片 <span>↗</span></button><details id="poster-more-options" class="poster-more-options"><summary>更多导出选项</summary><label>形式<select id="poster-mode"><option value="single" ${state.exportMode!=='carousel'?'selected':''}>单张海报</option><option value="carousel" ${state.exportMode==='carousel'?'selected':''}>轮播组图</option></select></label><button id="download-poster" class="secondary">下载当前页 <span>↓</span></button><button id="download-group" class="secondary download-group" hidden>电脑打包 ZIP ↓</button></details>${anonymous?'<a class="text-button" href="#profile">想申请认识？再完善个人卡片</a>':'<a class="text-button" href="#profile">调整资料与可见范围</a>'}<p class="fine-print">二维码跟随当前网站。本地预览码仅本机有效，请勿发到社交平台。</p></div></div></section>`);
  function updateLink(){const url=posterDestination(),personal=state.theme!==3&&state.posterMode!=='dayMaster'&&state.profile?.listed;$('#poster-link-content').innerHTML=`<p class="fine-print">${personal?'扫码可查看本人公开卡片，也能测自己的日主。':'扫码去测自己的日主，生成自己的卡片。'}</p><div class="link-box">${esc(url)}</div><button type="button" id="copy-share" class="text-button">复制邀请链接 ↗</button>`;$('#copy-share').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(url);toast('邀请链接已复制。');}catch{toast('请长按上方链接复制。');}});}
  function refresh(){drawPoster();updateLink();const group=state.exportMode==='carousel',count=carouselCount();$('#carousel-nav').hidden=!group;$('#carousel-qr-option').hidden=!group;$('#carousel-policy-note').hidden=!group;$('#download-group').hidden=!group;$('#generate-gallery').hidden=!group;$('#carousel-counter').textContent=((state.carouselPage||0)+1)+' / '+count;$('#carousel-prev').disabled=!state.carouselPage;$('#carousel-next').disabled=(state.carouselPage||0)>=count-1;$('#download-poster').innerHTML=(group?'下载当前页':'下载分享海报')+' <span>↓</span>';const size=posterFormat();$('#poster-format-note').textContent=size.width+' × '+size.height+' 建议版式，非平台强制规格。'+(size.portrait?'输出 PNG 图文 / 封面，不是 MP4 视频。':'');}
  document.querySelectorAll('[data-theme]').forEach(button=>button.addEventListener('click',()=>{state.theme=Number(button.dataset.theme);state.carouselPage=0;document.querySelectorAll('[data-theme]').forEach(other=>other.classList.toggle('active',other===button));$('#poster-person-settings').hidden=state.theme===3;$('#poster-confirm').checked=false;refresh();}));
