  if(anonymous){for(const [id,key] of [['poster-nickname','anonymousNickname'],['poster-hobbies','anonymousHobbies']])$('#'+id).addEventListener('input',typed=>{state[key]=typed.target.value;$('#poster-confirm').checked=false;drawPoster();});for(const [id,key] of [['poster-public-stem','anonymousStem'],['poster-public-zodiac','anonymousZodiac'],['poster-public-targets','anonymousTargets']])$('#'+id).addEventListener('change',changed=>{state[key]=changed.target.checked;state.caption=null;$('#poster-caption').value=defaultPosterCaption(posterSubject());$('#poster-confirm').checked=false;drawPoster();});}
  $('#download-poster').addEventListener('click',()=>{if(!$('#poster-confirm').checked){toast('请先检查预览，并勾选同意下载分享。');return;}const link=document.createElement('a');link.download=posterFileName(state.exportMode==='carousel'?state.carouselPage||0:0);link.href=$('#poster-canvas').toDataURL('image/png');link.click();event('poster_export');$('#download-poster').focus({preventScroll:true});});
  $('#poster-platform').addEventListener('change',selected=>{state.platform=selected.target.value;state.tailQr=null;state.carouselPage=0;$('#carousel-tail-qr').checked=tailQrEnabled();$('#poster-confirm').checked=false;refresh();});
